export interface ApiRouteContext {
  workspace: string;
  apiToken?: string;
  /**
   * Identity of the authenticated caller, supplied by the auth layer.
   * Never populated from request input — routes that attribute a write to a
   * person must read it from here rather than trusting a body field.
   */
  principal?: string;
  /** Present only after Studio has checked native-task browser admission. */
  nativeTasks?: NativeTaskApiContext;
}

export type ApiRouteHandler = (
  pathname: string,
  method: string,
  req: IncomingMessage,
  res: ServerResponse,
  context: ApiRouteContext
) => Promise<boolean>;

export interface ApiRouteDefinition {
  id: string;
  description: string;
  prefixes: readonly string[];
  methods: readonly string[];
  auth: ApiAuthPolicy;
  validationPolicy: ApiValidationPolicy;
  handler: ApiRouteHandler;
}

function workspaceRoute(
  handler: (
    pathname: string,
    method: string,
    req: IncomingMessage,
    res: ServerResponse,
    workspace: string
  ) => Promise<boolean>
): ApiRouteHandler {
  return (pathname, method, req, res, context) => handler(pathname, method, req, res, context.workspace);
}

