            severity: "LOW",
            agentId: auth.agentId,
            payload: {
              note: "answers payload ignored by server"
            }
          });
        }
        const out = await runAutoAnswer({
          workspace: options.workspace,
          agentId: auth.agentId,
          createPlan: true
        });
        const refreshed = refreshForecastForApi({
