      const bundleMatch = pathname.match(/^\/agents\/([^/]+)\/export\/bundle$/);
      if (bundleMatch && req.method === "POST") {
        if (!requireRouteRoles(["OPERATOR", "OWNER", "AUDITOR"])) {
