      if (pathname === "/toolhub/tools" && req.method === "GET") {
        if (!hasScope(auth, "toolhub:intent") && !hasAnyRole([...auth.roles], ["VIEWER", "OPERATOR", "APPROVER", "AUDITOR", "OWNER"])) {
