          !hasScope(auth, "toolhub:intent") &&
          !hasAnyRole([...auth.roles], ["VIEWER", "OPERATOR", "APPROVER", "AUDITOR", "OWNER"])
        ) {
          json(res, 403, { error: "missing toolhub scope" });
