      const agentApprovalStatusMatch = pathname.match(/^\/agent\/approvals\/([^/]+)\/status$/);
      if (agentApprovalStatusMatch && req.method === "GET") {
        const approvalId = decodeURIComponent(agentApprovalStatusMatch[1] ?? "");
