        if (typeof parsed.schemaId !== "string" || typeof parsed.file !== "string") {
          json(res, 400, { error: "schemaId and file are required" });
          return;
        }
        const out = standardValidateForApi({
          workspace: options.workspace,
          schemaId: parsed.schemaId,
