        }
        if (!requireRouteRoles(["VIEWER", "OPERATOR", "AUDITOR", "OWNER"])) {
          return;
        }
        const agentId = resolveAgentId(options.workspace, url.searchParams.get("agentId") ?? "default");
        const badge = passportBadgeForApi({
          workspace: options.workspace,
          agentId
        });
        json(res, 200, {
          badge: badge.badge
        });
